import numpy as np
sq=np.sqrt(P)
base={'1':np.ones_like(P),'t':t,'t2':t**2,'sq':sq,'P':P,'P2':P**2}
best=None
for w in np.linspace(0.05,3,300):
    cols=[]; names=[]
    for bn,bv in base.items():
        for tn,tv in [('1',np.ones_like(t)),('s',np.sin(w*t)),('c',np.cos(w*t))]:
            cols.append(bv*tv); names.append(bn+'*'+tn)
    A=np.array(cols).T
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    e=np.mean((A@c-dP_dt)**2)/np.var(dP_dt)
    if best is None or e<best[0]: best=(e,w,names,c)
print(best[0],best[1])
for n,v in zip(best[2],best[3]):
